import { ReactNode, FC } from 'react';

interface RadioProps {
    /** 是否选中 (受控) */
    checked?: boolean;
    /** 默认是否选中 (非受控) */
    defaultChecked?: boolean;
    /** 是否禁用 */
    disabled?: boolean;
    /** 单选框值 */
    value?: string | number;
    /** 选中状态变化回调 */
    onChange?: (checked: boolean) => void;
    /** 图标位置 */
    iconPosition?: 'left' | 'right';
    /** 选中颜色 */
    checkedColor?: string;
    /** 自定义类名 */
    className?: string;
    /** 子元素 (标签文字) */
    children?: ReactNode;
}
interface RadioGroupProps {
    /** 选中的值 (受控) */
    value?: string | number;
    /** 默认选中的值 (非受控) */
    defaultValue?: string | number;
    /** 是否禁用所有选框 */
    disabled?: boolean;
    /** 排列方向 */
    direction?: 'horizontal' | 'vertical';
    /** 值变化回调 */
    onChange?: (value: string | number) => void;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

type RadioComponent = FC<RadioProps> & {
    Group: FC<RadioGroupProps>;
};
declare const Radio: RadioComponent;
declare const RadioGroup: FC<RadioGroupProps>;

export { Radio, RadioGroup, Radio as default };
export type { RadioGroupProps, RadioProps };
